import sys
from functools import lru_cache

data = sys.stdin.read().split()
n = int(data[0])
A = tuple(int(x) for x in data[1:1 + n])

@lru_cache(maxsize=None)
def best(t):
    if len(t) == 1:
        return t[0]
    r = None
    for i in range(len(t) - 1):
        x, y = t[i], t[i + 1]
        for v in (x - y, y - x):
            c = best(t[:i] + (v,) + t[i + 2:])
            if r is None or c > r:
                r = c
    return r

print(best(A))

